package me.timschneeberger.rootlessjamesdsp.fusion

import android.app.Application
import me.timschneeberger.rootlessjamesdsp.interop.PreferenceCache
import me.timschneeberger.rootlessjamesdsp.utils.Constants
import org.junit.After
import org.junit.Before
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config

@RunWith(RobolectricTestRunner::class) @Config(sdk=[35],application=Application::class)
class DdcControllerTest {
    private val app:Application get()=RuntimeEnvironment.getApplication()
    private val p=DdcParameters;private val c=DdcController
    private val prefs get()=c.preferences(app)
    private val id=Any();private val owner=Any()
    private val sha="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
    private val otherSha="ffeeddccbbaa99887766554433221100ffeeddccbbaa99887766554433221100"
    @Before fun setup(){c.stopAudition(app,clearSnapshots=true);c.publishRuntime(app,emptyList());prefs.edit().clear().putString(p.FILE,"DDC/test.vdc").putBoolean(p.ENABLED,true).commit();p.apply(prefs,p.defaults().copy(professional=true));c.publishCapabilities(app,2);c.publishFile(app,id,"DDC/test.vdc","DDC/test.vdc",sha,"测试校正")}
    @After fun cleanup(){c.sessionClosed(app,id);c.stopAudition(app,clearSnapshots=true);c.publishRuntime(app,emptyList())}
    private fun reading(frames:Int,mode:Int=c.audition,stage:Int=0,epoch:Int=c.epoch,ready:Boolean=true,rate:Int=48000,host:Int=96000,source:String=sha,pending:Boolean=false):DdcController.Reading {
        val v=IntArray(80).apply {this[0]=1;this[1]=2;this[2]=rate;this[3]=1;this[4]=1;this[5]=1;this[6]=mode;this[8]=stage;this[12]=epoch;this[15]=if(ready)1 else 0;this[16]=host;this[17]=48000;this[18]=2;this[32]=1000;this[33]=1000;this[60]=if(pending)1 else 0;p.shaWords(source).copyInto(this,36);p.shaWords(source).copyInto(this,62)}
        return DdcController.Reading(id,true,frames,host,p.decode(v))
    }
    private fun active(){c.publishRuntime(app,listOf(reading(0)));c.publishRuntime(app,listOf(reading(512)))}
    @Test fun configurationContainsOnlyCurrentAcceptedFileAndBothSnapshotsCarrySameIdentity(){val sent=linkedMapOf<Int,IntArray>();assertTrue(c.sync(app,2,id){i,v->sent[i]=v;true});assertEquals(listOf(p.PACKET,p.TOOLS),sent.keys.toList());assertArrayEquals(p.capture(prefs.all).packet(true,sha),sent[p.PACKET]);assertEquals(132,sent[p.TOOLS]!!.size);assertArrayEquals(p.shaWords(sha),sent[p.TOOLS]!!.copyOfRange(40,48));assertArrayEquals(p.shaWords(sha),sent[p.TOOLS]!!.copyOfRange(104,112));prefs.edit().putBoolean(p.ENABLED,false).commit();sent.clear();assertTrue(c.sync(app,2,id){i,v->sent[i]=v;true});assertEquals(0,sent[p.PACKET]!![2])}
    @Test fun oldDriverGetsNoUnknownCommandsAndFailuresStopListening(){val ids=mutableListOf<Int>();assertTrue(c.sync(app,1,id){i,_->ids+=i;true});assertTrue(ids.isEmpty());active();for(fail in listOf(p.PACKET,p.TOOLS)){assertTrue(c.startAudition(app,owner,3));assertFalse(c.sync(app,2,id){i,_->i!=fail});assertEquals(0,c.audition)}}
    @Test fun activeFileIdentityReadyAndPendingGateAllListening(){assertFalse(c.canListen(app));active();assertTrue(c.canListen(app));for(mode in 1..3)assertTrue(c.startAudition(app,owner,mode));c.publishRuntime(app,listOf(reading(1024,pending=true)));assertFalse(c.canListen(app));assertEquals(0,c.audition);c.publishRuntime(app,listOf(reading(1536,source=otherSha)));assertFalse(c.canListen(app));c.publishRuntime(app,listOf(reading(2048)));assertTrue(c.canListen(app));c.publishRuntime(app,listOf(reading(2560,ready=false)));assertFalse(c.canListen(app))}
    @Test fun invalidSelectionPreservesLastAcceptedConfigurationAndStillAllowsExplicitOff(){active();c.saveComparison(app,owner,0);c.startAudition(app,owner,2);prefs.edit().putString(p.FILE,"DDC/broken.vdc").commit();c.publishFile(app,id,"DDC/broken.vdc","DDC/test.vdc",sha,"测试校正","系数无效");val sent=linkedMapOf<Int,IntArray>();assertTrue(c.sync(app,2,id){i,v->sent[i]=v;true});assertEquals(listOf(p.CLEAR),sent.keys.toList());assertArrayEquals(intArrayOf(0),sent[p.CLEAR]);assertEquals(sha,c.fileBindings().single {it.selectedPath=="DDC/broken.vdc"}.appliedSha256);assertFalse(c.hasComparison(0));assertNull(c.selectedSha256(app));prefs.edit().putString(p.ENABLED,"invalid power").commit();sent.clear();assertTrue(c.sync(app,2,id){i,v->sent[i]=v;true});assertEquals(listOf(p.CLEAR),sent.keys.toList());prefs.edit().putBoolean(p.ENABLED,false).commit();sent.clear();assertTrue(c.sync(app,2,id){i,v->sent[i]=v;true});assertEquals(listOf(p.CLEAR,p.OFF),sent.keys.toList());assertArrayEquals(intArrayOf(0),sent[p.OFF]);assertFalse(c.sync(app,2,id){_,_->false})}
    @Test fun switchingFileOrReplacingSameNameContentsClearsBothSnapshots(){active();c.saveComparison(app,owner,0);c.saveComparison(app,owner,1);c.publishFile(app,id,"DDC/test.vdc","DDC/test.vdc",sha,"测试校正",loading=true);assertFalse(c.canListen(app));assertNull(c.selectedSha256(app));val loadingSent=mutableListOf<Int>();assertTrue(c.sync(app,2,id){i,_->loadingSent+=i;true});assertEquals(listOf(p.CLEAR),loadingSent);assertFalse(c.hasComparison(0));prefs.edit().putBoolean(p.PROFESSIONAL,false).commit();loadingSent.clear();assertTrue(c.sync(app,2,id){i,_->loadingSent+=i;true});assertEquals(listOf(p.CLEAR,p.ORIGINAL),loadingSent);prefs.edit().remove(p.PROFESSIONAL).commit();loadingSent.clear();assertTrue(c.sync(app,2,id){i,_->loadingSent+=i;true});assertEquals(listOf(p.CLEAR,p.ORIGINAL),loadingSent);assertFalse(prefs.contains(p.PROFESSIONAL));prefs.edit().putBoolean(p.ENABLED,false).commit();loadingSent.clear();assertTrue(c.sync(app,2,id){i,_->loadingSent+=i;true});assertEquals(listOf(p.CLEAR,p.OFF),loadingSent);prefs.edit().putBoolean(p.ENABLED,true).putBoolean(p.PROFESSIONAL,true).commit();c.publishFile(app,id,"DDC/test.vdc","DDC/test.vdc",sha,"测试校正");active();assertTrue(c.saveComparison(app,owner,0));assertTrue(c.saveComparison(app,owner,1));c.publishFile(app,id,"DDC/test.vdc","DDC/test.vdc",otherSha,"新内容");assertFalse(c.hasComparison(0));assertFalse(c.hasComparison(1));assertEquals(otherSha,c.selectedSha256(app));c.saveComparison(app,owner,0);prefs.edit().putString(p.FILE,"DDC/another.vdc").commit();c.publishFile(app,id,"DDC/another.vdc","DDC/another.vdc",otherSha,"另一文件");assertFalse(c.hasComparison(0))}
    @Test fun abRequiresTwoSnapshotsAndOnlyCompletedTwoSecondMeasurementCanMatch(){active();assertFalse(c.measure(app,owner));assertFalse(c.startAudition(app,owner,4));c.saveComparison(app,owner,0);prefs.edit().putInt(p.ratio.key,317).commit();c.saveComparison(app,owner,1);assertTrue(c.measure(app,owner));assertFalse(c.setMatch(app,true));for(stage in listOf(1,2,4)){c.publishRuntime(app,listOf(reading(1024+stage*512,6,stage)));assertFalse(c.setMatch(app,true))};c.publishRuntime(app,listOf(reading(4096,6,3)));assertTrue(c.setMatch(app,true));assertTrue(c.startAudition(app,owner,4));assertFalse(prefs.all.keys.any {it.contains("snapshot") || it.contains("audition") || it.contains("match")});val before=c.epoch;c.measure(app,owner);assertNotEquals(before,c.epoch);assertFalse(c.match)}
    @Test fun changingAudioStopsPlaybackRetainsSameFileSnapshotsAndMetersDoNotInterruptMatch(){active();c.saveComparison(app,owner,0);c.saveComparison(app,owner,1);c.measure(app,owner);c.publishRuntime(app,listOf(reading(1024,6,3)));assertTrue(c.setMatch(app,true));assertTrue(c.startAudition(app,owner,4));c.sync(app,2,id){_,_->true};val epoch=c.epoch;for(key in listOf(p.METERS,p.RESPONSE))for(on in listOf(true,false)){prefs.edit().putBoolean(key,on).commit();c.sync(app,2,id){_,_->true};assertEquals(4,c.audition);assertTrue(c.match);assertEquals(epoch,c.epoch)};prefs.edit().putInt(p.lowGain.key,13).commit();c.sync(app,2,id){_,_->true};assertEquals(0,c.audition);assertTrue(c.hasComparison(0));assertTrue(c.hasComparison(1))}
    @Test fun anotherAudioModuleChangeStopsOnlyTemporaryPlayback(){active();c.sync(app,2,id){_,_->true};c.saveComparison(app,owner,0);c.startAudition(app,owner,2);PreferenceCache.getPreferences(app,Constants.PREF_TUBE).edit().putBoolean("tube_enable",true).commit();c.sync(app,2,id){_,_->true};assertEquals(0,c.audition);assertTrue(c.hasComparison(0));assertEquals(sha,c.selectedSha256(app))}
    @Test fun internalAndHostRateChangesIndependentlyClearSnapshotsAndListening(){active();for(hostChange in listOf(false,true)){c.saveComparison(app,owner,0);c.startAudition(app,owner,2);c.publishRuntime(app,listOf(reading(if(hostChange)2048 else 1024,2,rate=if(hostChange)44100 else 44100,host=if(hostChange)192000 else 96000)));assertFalse(c.hasComparison(0));assertEquals(0,c.audition)}}
    @Test fun stalePollingCannotReactivateAClosedOrDisabledSession(){active();c.saveComparison(app,owner,0);c.startAudition(app,owner,1);val poll=c.pollState();c.sessionClosed(app,id);c.publishRuntime(app,listOf(reading(1024,1)),poll);assertEquals(0,c.audition);assertFalse(c.canListen(app));c.publishFile(app,id,"DDC/test.vdc","DDC/test.vdc",sha,"测试校正");c.sessionEnabled(app,id,false);c.publishRuntime(app,listOf(reading(1536)));assertFalse(c.canListen(app));c.sessionEnabled(app,id,true);c.publishRuntime(app,listOf(reading(2048)));assertFalse(c.canListen(app));c.publishRuntime(app,listOf(reading(2560)));assertTrue(c.canListen(app))}
    @Test fun pauseCapabilityPowerAndProfessionalOffClearSnapshots(){active();c.saveComparison(app,owner,0);c.startAudition(app,owner,2);c.publishRuntime(app,listOf(reading(512,2)));assertFalse(c.hasComparison(0));assertEquals(0,c.audition);c.publishRuntime(app,listOf(reading(1024)));c.saveComparison(app,owner,0);c.publishCapabilities(app,0);assertFalse(c.hasComparison(0));c.publishCapabilities(app,2);c.saveComparison(app,owner,0);p.setProfessional(prefs,false);c.sync(app,2,id){_,_->true};assertFalse(c.hasComparison(0));p.setProfessional(prefs,true);c.saveComparison(app,owner,0);prefs.edit().putBoolean(p.ENABLED,false).commit();c.sync(app,2,id){_,_->true};assertFalse(c.hasComparison(0))}
    @Test fun rejectedPollingDoesNotClearOrOverwriteNewerState(){active();c.saveComparison(app,owner,0);val old=c.pollState();c.sessionEnabled(app,id,true);c.publishRuntime(app,listOf(reading(1024)),old);assertFalse(c.canListen(app));assertEquals(0,c.audition);assertFalse(c.hasComparison(0))}
}
